import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, expect, it } from "vitest";

import { declaration, undeclared, write } from "./declaration";

let root: string;

beforeEach(() => {
  root = mkdtempSync(join(tmpdir(), "env-"));
});

afterEach(() => {
  rmSync(root, { recursive: true, force: true });
});

const files = (files: Record<string, string>) => {
  for (const [name, text] of Object.entries(files)) writeFileSync(join(root, name), text);
};

it("will declare nothing without .env files", () => {
  expect(declaration(root)).toBeUndefined();
  expect(write(root)).toBeUndefined();
  expect(undeclared(root)).toEqual([]);
});

it("will declare keys with docs and sections", () => {
  files({
    ".env.example": "PLAIN=\n\n# Database\n\n# Postgres URL - */ escaped.\nDATABASE_URL=\nPOOL=\n\n# Mail\n\nSMTP_HOST=\n",
    ".env": "# Ignored, the example documents it first.\nDATABASE_URL=pg://local\nLOOSE=1\n\n# Ignored, the example places it first.\n\nSMTP_HOST=x\nPLAIN=1\n",
    ".env.local": "# Only on this machine.\nmy-key=1\n",
  });

  expect(declaration(root)).toBe(`\
// Generated by \`expressive env\` - key names and comments, no values.
import "@expressive/env";

declare module "@expressive/env" {
  interface Env {
    readonly PLAIN: string;
    readonly LOOSE?: string;
    /**
     * Only on this machine.
     */
    readonly "my-key"?: string;

    // Database

    /**
     * Postgres URL - *\\/ escaped.
     *
     * @category Database
     */
    readonly DATABASE_URL: string;
    /**
     * @category Database
     */
    readonly POOL: string;

    // Mail

    /**
     * @category Mail
     */
    readonly SMTP_HOST: string;
  }
}
`);
});

it("will write once, then report current", () => {
  files({ ".env": "A=1" });

  expect(write(root)).toBe("written");
  expect(readFileSync(join(root, "env.d.ts"), "utf8")).toContain("readonly A: string;");
  expect(write(root)).toBe("current");
});

it("will require .env keys only without an example", () => {
  files({ ".env": "A=1", ".env.local": "B=1" });

  expect(declaration(root)).toContain("readonly A: string;");
  expect(declaration(root)).toContain("readonly B?: string;");
});

it("will not depend on which local files exist", () => {
  files({ ".env.example": "A=", ".env": "A=1\nB=1", ".env.local": "C=1" });
  write(root);
  rmSync(join(root, ".env"));
  rmSync(join(root, ".env.local"));

  expect(undeclared(root)).toEqual([]);
  expect(declaration(root)!.split("\n")[0]).toBe("// Generated by `expressive env` - key names and comments, no values.");
});

it("will list keys env.d.ts does not declare", () => {
  files({ ".env": "A=1\nmy-key=1" });
  expect(undeclared(root)).toEqual(["A", "my-key"]);

  write(root);
  expect(undeclared(root)).toEqual([]);

  files({ ".env.local": "B=2" });
  expect(undeclared(root)).toEqual(["B"]);
});

it("will skip directories and non-env files", () => {
  mkdirSync(join(root, ".env.d"));
  files({ ".env": "A=1", ".env.swp": "JUNK=1", ".env.vault": "JUNK=1" });

  expect(declaration(root)).not.toContain("JUNK");
});

it("will read past a byte order mark", () => {
  files({ ".env": "\uFEFFA=1" });

  expect(declaration(root)).toContain("readonly A: string;");
});
